package com.masterclass.inventory.integration; import org.junit.jupiter.api.Test; import org.springframework.boot.test.context.SpringBootTest; import org.springframework.boot.test.web.server.LocalServerPort; import org.springframework.test.context.DynamicPropertyRegistry; import org.springframework.test.context.DynamicPropertySource; import org.testcontainers.containers.MSSQLServerContainer; import org.testcontainers.junit.jupiter.*; import static org.assertj.core.api.Assertions.*;
@Testcontainers @SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT) class ProductApiIntegrationTest { @Container static MSSQLServerContainer<?> sql=new MSSQLServerContainer<>("mcr.microsoft.com/mssql/server:2022-latest").acceptLicense(); @LocalServerPort int port; @DynamicPropertySource static void props(DynamicPropertyRegistry r){ r.add("spring.datasource.url", sql::getJdbcUrl); r.add("spring.datasource.username", sql::getUsername); r.add("spring.datasource.password", sql::getPassword); r.add("spring.jpa.hibernate.ddl-auto", ()->"create-drop"); } @Test void contextStarts(){ assertThat(port).isPositive(); } }
